    /**
     * Format a timestamp in seconds using active locale.
     *
     * @param {number} sec Unix timestamp in seconds.
     * @param {string} [locale] Active locale.
     * @return {string} Formatted date and time.
     */
    function formatDateTime(sec, locale) {
        var d = new Date(sec * 1000);
        var loc = locale || undefined;
        try {
            var formatter = new Intl.DateTimeFormat(loc, {
                day: '2-digit',
                month: '2-digit',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
                hour12: false
            });
            return formatter.format(d);
        } catch (e) {
            var yr = d.getFullYear();
            var mo = String(d.getMonth() + 1).padStart(2, '0');
            var dy = String(d.getDate()).padStart(2, '0');
            var hr = String(d.getHours()).padStart(2, '0');
            var mn = String(d.getMinutes()).padStart(2, '0');
            return dy + '/' + mo + '/' + yr + ' ' + hr + ':' + mn;
        }
    }

    /**
     * Format duration in seconds into a readable string.
     *
     * @param {number} sec Duration in seconds.
     * @return {string} Formatted duration.
     */
    function formatDuration(sec) {
        var days = Math.floor(sec / 86400);
        var hours = Math.round((sec % 86400) / 3600);
        if (days > 0 && hours > 0) {
            return days + 'd ' + hours + 'h';
        } else if (days > 0) {
            return days + 'd';
        }
        return Math.max(1, hours) + 'h';
    }

    /**
     * Show a duration only when both endpoints represent stored dates.
     *
     * @param {Object} item Activity or milestone.
     * @return {string} Duration label.
     */
    function formatItemDuration(item) {
        if (item.ismilestone) {
            return item.typelabel;
        }
        if (item.startenabled === false || item.endenabled === false) {
            return '—';
        }
        return formatDuration(item.dateend - item.datestart);
    }

    /** Format a displayed effort value without changing the stored estimate. */
    function formatEffort(value, locale) {
        try {
            return new Intl.NumberFormat(locale || undefined, {
                minimumFractionDigits: 1,
                maximumFractionDigits: 1
            }).format(Number(value));
        } catch (e) {
            return Number(value).toFixed(1);
        }
    }

    /**
     * Convert Unix timestamp in seconds to datetime-local input string format (YYYY-MM-DDTHH:mm).
     *
     * @param {number} sec Unix timestamp in seconds.
     * @return {string} Datetime local string.
     */
    function timestampToDateTimeLocal(sec) {
        var d = new Date(sec * 1000);
        var yr = d.getFullYear();
        var mo = String(d.getMonth() + 1).padStart(2, '0');
        var dy = String(d.getDate()).padStart(2, '0');
        var hr = String(d.getHours()).padStart(2, '0');
        var mn = String(d.getMinutes()).padStart(2, '0');
        return yr + '-' + mo + '-' + dy + 'T' + hr + ':' + mn;
    }

    /**
     * Convert datetime-local input string format (YYYY-MM-DDTHH:mm) to Unix timestamp in seconds.
     *
     * @param {string} str Datetime local string.
     * @return {number} Unix timestamp in seconds.
     */
    function dateTimeLocalToTimestamp(str) {
        if (!str) {
            return 0;
        }
        var parts = str.split('T');
        var dateParts = parts[0].split('-');
        if (dateParts.length !== 3) {
            return 0;
        }
        var timeParts = parts.length > 1 ? parts[1].split(':') : ['0', '0'];
        var d = new Date(
            parseInt(dateParts[0], 10),
            parseInt(dateParts[1], 10) - 1,
            parseInt(dateParts[2], 10),
            parseInt(timeParts[0], 10),
            parseInt(timeParts[1], 10),
            0
        );
        return Math.floor(d.getTime() / 1000);
    }

    /**
     * Format a date-only milestone without introducing a visible time.
     *
     * @param {number} sec Unix timestamp in seconds.
     * @param {string} [locale] Active locale.
     * @return {string} Local date.
     */
    function formatDateOnly(sec, locale) {
        return new Intl.DateTimeFormat(locale || undefined, {
            day: '2-digit', month: '2-digit', year: 'numeric'
        }).format(new Date(sec * 1000));
    }

    /**
     * Keep date-selector milestones at the browser's local midnight.
     *
     * @param {number} sec Unix timestamp in seconds.
     * @return {number} Midnight timestamp.
     */
    function startOfLocalDay(sec) {
        var date = new Date(sec * 1000);
        date.setHours(0, 0, 0, 0);
        return Math.floor(date.getTime() / 1000);
    }

    /** Shift a stored date by local calendar days or exact hours. */
    function shiftSnappedDate(sec, steps, unit) {
        if (unit !== 'days') {
            return sec + steps * 3600;
        }
        var date = new Date(sec * 1000);
        date.setDate(date.getDate() + steps);
        return Math.floor(date.getTime() / 1000);
    }

    /** Copy just the local calendar date, preserving the original clock time. */
    function dateWithOriginalClock(proposed, original) {
        var date = new Date(proposed * 1000);
        var clock = new Date(original * 1000);
        date.setHours(clock.getHours(), clock.getMinutes(), clock.getSeconds(), 0);
        return Math.floor(date.getTime() / 1000);
    }

    /** Number of calendar days between two local dates, independent of DST. */
    function localDayDifference(from, to) {
        var first = new Date(from * 1000);
        var last = new Date(to * 1000);
        return Math.round((Date.UTC(last.getFullYear(), last.getMonth(), last.getDate()) -
            Date.UTC(first.getFullYear(), first.getMonth(), first.getDate())) / 86400000);
    }

    /** Find the nearest local day boundary to the pointer's proposed shift. */
    function snapStepsForDelta(initial, rawDelta, unit) {
        if (unit !== 'days') {
            return Math.round(rawDelta / 3600);
        }
        var proposed = initial + rawDelta;
        var day = localDayDifference(initial, proposed);
        var best = day;
        [day - 1, day + 1].forEach(function(candidate) {
            if (Math.abs(shiftSnappedDate(initial, candidate, 'days') - proposed) <
                    Math.abs(shiftSnappedDate(initial, best, 'days') - proposed)) {
                best = candidate;
            }
        });
        return best;
    }

    /** Find the furthest whole snap step that stays within the allowed bounds. */
    function fitSnapSteps(requested, allowed) {
        if (allowed(requested)) {
            return requested;
        }
        if (!allowed(0)) {
            return 0;
        }
        var sign = requested < 0 ? -1 : 1;
        var low = 0;
        var high = Math.abs(requested);
        while (high - low > 1) {
            var middle = Math.floor((low + high) / 2);
            if (allowed(middle * sign)) {
                low = middle;
            } else {
                high = middle;
            }
        }
        return low * sign;
    }

    /** Align to a target's date or hour without replacing the source minutes. */
    function snapStepForTarget(initial, target, unit) {
        var source = new Date(initial * 1000);
        var aligned = new Date(target * 1000);
        if (unit === 'days') {
            aligned.setHours(source.getHours(), source.getMinutes(), source.getSeconds(), 0);
        } else {
            aligned.setMinutes(source.getMinutes(), source.getSeconds(), 0);
        }
        var steps = unit === 'days' ? localDayDifference(initial, target) :
            Math.round((aligned.getTime() / 1000 - initial) / 3600);
        return {steps: steps, time: shiftSnappedDate(initial, steps, unit)};
    }

    /**
     * Get weekend days for the given locale.
     * Returns an array of ISO day numbers: 1 (Monday) to 7 (Sunday).
     *
     * @param {string} [locale] BCP47 locale or Moodle language code.
     * @return {Array<number>}
     */
    function getLocaleWeekendDays(locale) {
        if (typeof Intl !== 'undefined' && Intl.Locale) {
            try {
                var tag = String(locale || 'default').replace(/_/g, '-');
                var loc = new Intl.Locale(tag);
                var info = loc.weekInfo || (loc.getWeekInfo ? loc.getWeekInfo() : null);
                if (info && Array.isArray(info.weekend) && info.weekend.length > 0) {
                    return info.weekend;
                }
            } catch (e) {
                // Fallback below.
            }
        }
        return [6, 7];
    }

    /** First day of the locale's natural week, using ISO day numbers. */
    function getLocaleFirstDay(locale) {
        if (typeof Intl !== 'undefined' && Intl.Locale) {
            try {
                var tag = String(locale || 'default').replace(/_/g, '-');
                var loc = new Intl.Locale(tag);
                var info = loc.weekInfo || (loc.getWeekInfo ? loc.getWeekInfo() : null);
                if (info && info.firstDay >= 1 && info.firstDay <= 7) {
                    return info.firstDay;
                }
            } catch (e) {
                // Fallback below.
            }
        }
        return 1;
    }

    /**
     * Check whether a given Date is on a weekend according to weekend days.
     *
     * @param {Date} date Date instance.
     * @param {Array<number>} weekendDays Array of ISO day numbers (1 = Mon ... 7 = Sun).
     * @return {boolean}
     */
    function isDateWeekend(date, weekendDays) {
        var day = date.getDay();
        var isoDay = (day === 0) ? 7 : day;
        return weekendDays.indexOf(isoDay) !== -1;
    }

    /**
     * Choose a bar gesture. Narrow bars reserve a central area for moving;
     * their outer quarters remain resize targets.
     *
     * @param {Object} item Activity item.
     * @param {number} width Rendered bar width in pixels.
     * @param {number} clickX Pointer position within the bar in pixels.
     * @param {boolean} startHandle Whether the start handle received the event.
     * @param {boolean} endHandle Whether the end handle received the event.
     * @return {string} Move or resize mode.
     */
    function getBarDragMode(item, width, clickX, startHandle, endHandle) {
        if (item.ismilestone) {
            return 'move';
        }
        if (item.isopenstart) {
            return endHandle || clickX >= width * 0.75 ? 'resize-end' : 'none';
        }
        if (width < 24) {
            if (clickX <= width * 0.25) {
                return 'resize-start';
            }
            if (!item.isopenended && clickX >= width * 0.75) {
                return 'resize-end';
            }
            return 'move';
        }
        if (startHandle || (endHandle && clickX < 12 && clickX < width / 2)) {
            return 'resize-start';
        }
        return endHandle ? 'resize-end' : 'move';
    }

    var EFFORT_DAY = 86400;
    var EFFORT_DEFAULT = 5;
    var EFFORT_TAIL_DAYS = 2;
    var EFFORT_SCALE_MAX = 4;
    var EFFORT_DAYS_PER_WEEK = 7;
    // Five labels (0–4) fit at 15px intervals with a little canvas padding.
    var EFFORT_PLOT_HEIGHT = 72;
